/* KO / daemon 的块流密钥，运行时生成（不占 .rodata）。
   公式必须与 tools/obf_assets.py 的 big_keystream() 逐字节一致，
   一旦不一致解密结果就是噪声（落盘后 KO 加载失败）。*/
#define BIG_KS_LEN 65536
size_t asset_ks_len(void) { return BIG_KS_LEN; }
void asset_ks(uint8_t *out, size_t n) {
    for (size_t i = 0; i < n; i++)
        out[i] = (uint8_t)(OBF_SKEY((i + 0x3c) & 0xFF)
                          ^ (uint8_t)((i * 31) & 0xFF)
                          ^ OBF_SKEY((i >> 8) & 0xFF)
                          ^ (uint8_t)((i >> 12) & 0xFF));
}

/* 运行时取 UMH 脚本。
   带 ASSET_MAGIC 头 = 密文，XOR 解密；
   没有头 = 明文（--no-encrypt 交付态），原样拷贝。同一套代码兼容两种资产。*/
static const uint8_t tool_magic[8] = {0x00,0x4f,0x42,0x46,0x41,0x53,0x01,0x00};
int tool_decode(uint8_t *out, size_t out_cap, size_t *out_len) {
    size_t n = sizeof(tool_enc);
    const uint8_t *src = tool_enc;
    int enc = 0;
    if (n >= 8 && memcmp(tool_enc, tool_magic, 8) == 0) { enc = 1; src += 8; n -= 8; }
    if (out_cap < n + 1) return -1;
    for (size_t i = 0; i < n; i++)
        out[i] = enc ? (uint8_t)(src[i] ^ (uint8_t)(0x5a ^ OBF_SKEY((i + 0x5a) & 0xFF) ^ (uint8_t)(i * 31))) : src[i];
    out[n] = 0;
    *out_len = n;
    return 0;
}

