/* 明文 DER 的 SHA-256，按 sbox 掩码存（与 obf_data.h 同一手法）*/
static const uint8_t pk_hash_mask[32] = {
    0x27,0x6f,0x4a,0x9b,0x3c,0x10,0xae,0x38,0x1c,0xc2,0xfd,0xae,0x13,0xad,0xaf,0xa7,0x2c,0x95,0x56,0x45,0xb0,0x67,0x04,0xa8,0xee,0x7f,0xf0,0x75,0xd0,0xfb,0xf8,0xdf
};

/* 运行时解密 + 完整性校验。资产被替换 => hash 对不上 => 返回 NULL，
   verifyLicense 直接失败（换 public.pem 伪造激活码这条路被堵死）。*/
int pk_decode(uint8_t *out, size_t out_cap, size_t *out_len) {
    if (out_cap < sizeof(pk_enc)) return -1;
    for (size_t i = 0; i < sizeof(pk_enc); i++)
        out[i] = pk_enc[i] ^ (uint8_t)(0xa5 ^ OBF_SKEY((i + 0xa5) & 0xFF) ^ (uint8_t)(i * 31));
    uint8_t d[32];
    sha256_ctx c; sha256_init(&c); sha256_update(&c, out, sizeof(pk_enc)); sha256_final(&c, d);
    for (int i = 0; i < 32; i++)
        if (d[i] != (uint8_t)(pk_hash_mask[i] ^ OBF_SKEY(i))) return -2;
    *out_len = sizeof(pk_enc);
    return 0;
}
